from collections import deque

def components(grid,val):
    R,C=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(R):
      for c in range(C):
       if grid[r][c]==val and (r,c) not in seen:
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
         x,y=q.pop(); comp.append((x,y))
         for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
          xx,yy=x+dx,y+dy
          if 0<=xx<R and 0<=yy<C and grid[xx][yy]==val and (xx,yy) not in seen:
           seen.add((xx,yy));q.append((xx,yy))
        out.append(comp)
    return out

def transform(grid):
    R,C=len(grid),len(grid[0])
    comps=components(grid,4)
    # target is the largest 4-component, with the topmost component breaking ties
    comps.sort(key=lambda z:(-len(z),min(r for r,c in z),min(c for r,c in z)))
    target,source=comps[:2]
    def adjacent_sevens(comp):
      s=set(comp); return {(r+dr,c+dc) for r,c in comp for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<R and 0<=c+dc<C and grid[r+dr][c+dc]==7}
    t7=adjacent_sevens(target); s7=adjacent_sevens(source)
    tr,tc=min(t7); sr,sc=min(s7); dr,dc=tr-sr,tc-sc
    r0=min(r for r,c in target);r1=max(r for r,c in target);c0=min(c for r,c in target);c1=max(c for r,c in target)
    out=[[1]*(c1-c0+1) for _ in range(r1-r0+1)]
    for r,c in target: out[r-r0][c-c0]=4
    for r,c in source: 
      rr,cc=r+dr-r0,c+dc-c0
      if 0<=rr<len(out) and 0<=cc<len(out[0]):out[rr][cc]=4
    for r,c in t7:
      rr,cc=r-r0,c-c0
      if 0<=rr<len(out) and 0<=cc<len(out[0]):out[rr][cc]=4
    return out
